/** @type {import('@tryghost/api-framework').Controller} */
const controller = {
    docName: 'audit_logs',

    browse: {
        headers: {
            cacheInvalidate: false
        },
        options: [
            'page',
            'limit',
            'fields',
            'filter',
            'order'
        ],
        permissions: true,
        query(frame) {
            return models.AuditLog.findPage(frame.options);
        }
    },

    read: {
        headers: {
            cacheInvalidate: false
        },
        options: [
            'fields'
