const assert = require('node:assert/strict');
const {agentProvider, fixtureManager, matchers} = require('../../utils/e2e-framework');
const {anyContentVersion, anyEtag, anyObjectId, anyISODateTime, anyString, anyObject} = matchers;
const localUtils = require('./utils');

const auditLogMatcher = {
    id: anyObjectId,
    created_at: anyISODateTime
};

describe('Audit Logs API', function () {
    let agent;

    before(async function () {
        agent = await agentProvider.getAdminAPIAgent();
        await fixtureManager.init('posts', 'users');
        await agent.loginAsOwner();
    });

    describe('Browse', function () {
        it('Can browse audit logs', async function () {
            await agent
                .get('audit_logs/')
                .expectStatus(200)
                .matchHeaderSnapshot({
                    'content-version': anyContentVersion,
                    etag: anyEtag
                })
                .matchBodySnapshot({
                    audit_logs: new Array(50).fill(auditLogMatcher)
                })
                .expect(({body}) => {
                    localUtils.API.checkResponse(body, 'audit_logs');
                    assert.ok(body.audit_logs.length > 0, 'Should have audit logs');

                    // Check first audit log has expected properties
                    const firstLog = body.audit_logs[0];
                    assert.ok(firstLog.id, 'Should have id');
                    assert.ok(firstLog.created_at, 'Should have created_at');
                });
        });

        it('Can paginate audit logs', async function () {
            await agent
                .get('audit_logs/?page=1&limit=5')
                .expectStatus(200)
                .matchHeaderSnapshot({
                    'content-version': anyContentVersion,
                    etag: anyEtag
                })
                .matchBodySnapshot({
                    audit_logs: new Array(5).fill(auditLogMatcher)
                })
                .expect(({body}) => {
                    assert.equal(body.audit_logs.length, 5, 'Should return 5 audit logs');
                    assert.ok(body.meta.pagination, 'Should have pagination metadata');
                    assert.equal(body.meta.pagination.page, 1, 'Should be page 1');
                    assert.equal(body.meta.pagination.limit, 5, 'Should have limit 5');
                });
        });

        it('Returns 401 for unauthenticated request', async function () {
            const unauthenticatedAgent = await agentProvider.getAdminAPIAgent();

            await unauthenticatedAgent
                .get('audit_logs/')
                .expectStatus(401);
        });
    });

    describe('Read', function () {
        it('Can read a single audit log by id', async function () {
            // First browse to get an ID
            const browseRes = await agent
                .get('audit_logs/?limit=1')
                .expectStatus(200);

            const auditLogId = browseRes.body.audit_logs[0].id;

            await agent
                .get(`audit_logs/${auditLogId}/`)
                .expectStatus(200)
                .matchHeaderSnapshot({
                    'content-version': anyContentVersion,
                    etag: anyEtag
                })
                .matchBodySnapshot({
                    audit_logs: [auditLogMatcher]
                })
                .expect(({body}) => {
                    localUtils.API.checkResponse(body.audit_logs[0], 'audit_log');
                    assert.equal(body.audit_logs[0].id, auditLogId, 'Should return the requested audit log');
                });
        });

        it('Returns 401 for unauthenticated request', async function () {
            const unauthenticatedAgent = await agentProvider.getAdminAPIAgent();
            const browseRes = await agent
                .get('audit_logs/?limit=1')
                .expectStatus(200);

            const auditLogId = browseRes.body.audit_logs[0].id;

            await unauthenticatedAgent
                .get(`audit_logs/${auditLogId}/`)
                .expectStatus(401);
        });
    });
});

